# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GÜZEL AHLAKIN İKİ TEMEL TAŞI: DOĞRULUK (SIDK) VE GÜVENİLİRLİK (EMANET)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Doğruluk (Sıdk) ve Sâdık Olmak</text>\n  <text x="44" y="100" font-size="11" fill="#334155">• İnsanın niyetinde, sözünde ve davranışlarında</text>\n  <text x="44" y="116" font-size="11" fill="#334155">  dürüst olması; yalan ve riyadan kaçınmasıdır.</text>\n  <text x="44" y="140" font-size="11.5" font-weight="bold" fill="#1e40af">• Ayet: &quot;Emrolunduğun gibi dosdoğru ol!&quot;</text>\n  <text x="54" y="156" font-size="10.5" fill="#475569">(Hûd suresi, 112. ayet)</text>\n  <text x="44" y="180" font-size="11.5" font-weight="bold" fill="#1e40af">• Hadis: &quot;Doğruluk iyiliğe (birr), iyilik de</text>\n  <text x="54" y="196" font-size="11.5" font-weight="bold" fill="#1e40af">cennete götürür.&quot;</text>\n  <text x="44" y="218" font-size="11" fill="#334155">* Doğru sözlü ve dürüst kişiye SÂDIK denir.</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Güvenilirlik (Emanet) ve el-Emîn</text>\n  <text x="378" y="100" font-size="11" fill="#334155">• Sözünde durmak, sırları saklamak, emanetleri</text>\n  <text x="378" y="116" font-size="11" fill="#334155">  korumak ve hiç kimseyi aldatmamaktır.</text>\n  <text x="378" y="140" font-size="11.5" font-weight="bold" fill="#166534">• Hz. Peygamber\'in Unvanı: Muhammedü\'l-Emîn</text>\n  <text x="388" y="156" font-size="10.5" fill="#475569">(Güvenilir Muhammed — peygamberlikten önce bile)</text>\n  <text x="378" y="180" font-size="11.5" font-weight="bold" fill="#166534">• Hadis: &quot;Bizi aldatan bizden değildir.&quot;</text>\n  <text x="378" y="204" font-size="11" fill="#334155">* Can, akıl, sağlık, aile ve kamu malı da</text>\n  <text x="378" y="220" font-size="11" fill="#334155">  korunması gereken birer emanettir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ADALET (HAKKANİYET) VE YARDIMLAŞMA (TEÂVÜN / İNFAK / ÎSÂR)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Adalet İlkesi ve Kul Hakkı</text>\n  <text x="44" y="100" font-size="11" fill="#334155">• Tanım: Herkese hakkını vermek, her şeyi yerli</text>\n  <text x="44" y="116" font-size="11" fill="#334155">  yerine koymak ve eşitlik/hakkaniyetle hükmetmektir.</text>\n  <text x="44" y="140" font-size="11.5" font-weight="bold" fill="#92400e">• Zıddı: Zulüm (haksızlık) ve tarafgirliktir.</text>\n  <text x="44" y="164" font-size="11" fill="#334155">• Nahl Suresi, 90: &quot;Şüphesiz Allah adaleti,</text>\n  <text x="44" y="180" font-size="11" fill="#334155">  iyilik yapmayı (ihsanı) ve yakınlara yardım</text>\n  <text x="44" y="196" font-size="11" fill="#334155">  etmeyi emreder...&quot;</text>\n  <text x="44" y="218" font-size="11" font-weight="bold" fill="#b45309">* Kendi aleyhine bile olsa adil şahitlik (Nisâ, 135).</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">4. Yardımlaşma ve Dayanışma Kavramları</text>\n  <text x="378" y="100" font-size="11" fill="#334155">• Mâide Suresi, 2: &quot;İyilik ve takva üzere</text>\n  <text x="378" y="116" font-size="11" fill="#334155">  yardımlaşın; günah ve düşmanlıkta yardımlaşmayın.&quot;</text>\n  <text x="378" y="140" font-size="11.5" font-weight="bold" fill="#991b1b">• İnfak:</text>\n  <text x="425" y="140" font-size="11" fill="#334155">Allah rızası için maldan harcama yapma.</text>\n  <text x="378" y="164" font-size="11.5" font-weight="bold" fill="#991b1b">• Sadaka:</text>\n  <text x="435" y="164" font-size="11" fill="#334155">Maddi ve manevi her türlü güzel iyilik.</text>\n  <text x="378" y="188" font-size="11.5" font-weight="bold" fill="#991b1b">• Îsâr (Diğergamlık):</text>\n  <text x="388" y="206" font-size="11" fill="#334155">Kendi ihtiyacı varken bile din kardeşini kendi</text>\n  <text x="388" y="222" font-size="11" fill="#334155">nefsine tercih etme (Ensar\'ın fedakârlığı).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AHLAK İLKELERİNİN BİREYSEL VE TOPLUMSAL HUZURA ETKİSİ</text>\n  <rect x="25" y="50" width="650" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kavram — Zıt Davranış — Toplumsal Sonuç Tablosu</text>\n  <text x="45" y="106" font-size="11.5" font-weight="bold" fill="#1e40af">1. Doğruluk (Sıdk)</text>\n  <text x="230" y="106" font-size="11" fill="#b91c1c">Zıddı: Yalan (Kizb) ve Riya</text>\n  <text x="430" y="106" font-size="11" fill="#15803d">→ Söz ve davranış birliği, iç huzur sağlar.</text>\n  <text x="45" y="136" font-size="11.5" font-weight="bold" fill="#1e40af">2. Güvenilirlik (Emanet)</text>\n  <text x="230" y="136" font-size="11" fill="#b91c1c">Zıddı: Hıyanet ve Aldatma</text>\n  <text x="430" y="136" font-size="11" fill="#15803d">→ Karşılıklı güven ve ticaret ahlakı kurar.</text>\n  <text x="45" y="166" font-size="11.5" font-weight="bold" fill="#1e40af">3. Adalet (Kıst / Adl)</text>\n  <text x="230" y="166" font-size="11" fill="#b91c1c">Zıddı: Zulüm ve Kayırma</text>\n  <text x="430" y="166" font-size="11" fill="#15803d">→ Hakları korur, toplumsal barışı yaşatır.</text>\n  <text x="45" y="196" font-size="11.5" font-weight="bold" fill="#1e40af">4. Yardımlaşma (Teâvün)</text>\n  <text x="230" y="196" font-size="11" fill="#b91c1c">Zıddı: Cimrilik ve Bencillik</text>\n  <text x="430" y="196" font-size="11" fill="#15803d">→ Kardeşlik bağlarını ve birliği güçlendirir.</text>\n  <text x="350" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#334155">Hadis-i Şerif: &quot;Müminler birbirlerini sevmede ve korumada tek bir vücudun organları gibidir.&quot;</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
